const { readFileSync } = await import('node:fs');
const jsonPath = process.env.JSON_PATH;
const outPath = process.env.OUTPUT_PATH;
if (!jsonPath) throw new Error('Missing JSON_PATH env var');
if (!outPath) throw new Error('Missing OUTPUT_PATH env var');
const jsonContent = readFileSync(jsonPath, 'utf8');
globalThis.jsonContent = jsonContent;
globalThis.outputPath = outPath;

const { json2xml } = await import('xml-js');
const xml = json2xml(globalThis.jsonContent, { compact: true, spaces: 2 });
if (typeof xml !== 'string') throw new Error('Conversion did not produce XML string');
globalThis.xmlResult = xml;

const { writeFileSync } = await import('node:fs');
writeFileSync(globalThis.outputPath, globalThis.xmlResult, 'utf8');
console.log(JSON.stringify({ xml_path: globalThis.outputPath }));
